<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Marketing</title><style>
:root{--bg:#0a0f1f;--side:#0f172a;--card:#151e33;--line:#2a3654;--text:#fff;--muted:#9fb0cc;--ok:#2ee6a6;--warn:#ffc21a;--accent:#8190ff;--danger:#ff6f87}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:Inter,Arial,sans-serif}.shell{display:grid;grid-template-columns:250px 1fr;min-height:100vh}.side{padding:28px 24px;border-right:1px solid var(--line);background:var(--side);position:sticky;top:0;height:100vh}.brand{font-size:30px;font-weight:800;margin-bottom:38px}.brand i{font-style:normal;color:var(--accent)}nav a{display:block;color:#c7d1e5;text-decoration:none;font-size:16px;margin:0 0 24px}main{padding:40px 30px;min-width:0}.lead{display:flex;justify-content:space-between;gap:18px;align-items:flex-start}.lead h1{font-size:34px;margin:0 0 12px}.lead p{color:var(--muted);font-size:17px;margin:0}.version{color:var(--muted);font-size:12px;border:1px solid var(--line);padding:8px 10px;border-radius:20px}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:22px 0}.card{background:var(--card);border:1px solid var(--line);border-radius:18px;padding:20px}.metric{font-size:32px;font-weight:800;margin-top:10px}.muted{color:var(--muted)}h2{font-size:22px;margin:0 0 15px}.badge{display:inline-block;font-size:12px;border-radius:10px;padding:6px 9px;background:#173d35;color:var(--ok)}.pending{background:#3a3012;color:var(--warn)}.ready{background:#18354b;color:#81c8ff}.endpoint{font:12px ui-monospace,Consolas,monospace;background:#0d1425;padding:10px;border-radius:10px;overflow-wrap:anywhere}.split{display:grid;grid-template-columns:.8fr 1.2fr;gap:14px;margin-bottom:14px}.events .row,.platform{display:flex;justify-content:space-between;align-items:center;padding:13px 0;border-bottom:1px solid var(--line)}.events .row:last-child,.platform:last-child{border:0}.conversations{display:grid;gap:10px}.conv{border:1px solid var(--line);border-radius:14px;padding:14px;background:#111a2e}.conv-top{display:flex;justify-content:space-between;gap:12px}.who{font-weight:750}.client{color:#9cb0d6;font-size:12px;margin-top:4px}.msg{margin:12px 0;color:#dce4f2}.meta{font-size:11px;color:#7688aa}.tags{display:flex;gap:7px;flex-wrap:wrap;margin-top:12px}.tagbtn{border:1px solid #344366;background:#172139;color:#dce5f7;border-radius:9px;padding:7px 10px;cursor:pointer;font-size:12px}.tagbtn.active{background:#253566;border-color:#8291ff;color:#fff}.empty{color:var(--muted);padding:18px 0}.tiny{font-size:12px;color:#7585a4;margin-top:12px}.dir{font-size:11px;border:1px solid var(--line);padding:3px 6px;border-radius:8px;color:#9fb0cc}.ad{font-size:11px;color:#9db5ff;margin-top:8px}@media(max-width:980px){.shell{grid-template-columns:1fr}.side{display:none}.grid{grid-template-columns:1fr 1fr}.split{grid-template-columns:1fr}}@media(max-width:560px){main{padding:22px 14px}.grid{grid-template-columns:1fr}}
</style></head><body><div class="shell"><aside class="side"><div class="brand">Marketing<i>.</i></div><nav><a href="#">Dashboard</a><a href="#conversations">Conversations</a><a href="#events">Event Mapping</a><a href="#platforms">Platforms</a></nav></aside><main><div class="lead"><div><h1>Marketing Conversion Hub</h1><p>WhatsApp Business App → YCloud → Tags → realtime ad signals</p></div><div class="version" id="version">Checking…</div></div><div class="grid"><div class="card"><div class="muted">Clients / WABAs</div><div class="metric" id="clientsCount">—</div></div><div class="card"><div class="muted">WhatsApp Numbers</div><div class="metric" id="numbersCount">—</div></div><div class="card"><div class="muted">Conversations</div><div class="metric" id="conversationsCount">—</div></div><div class="card"><div class="muted">Events Today</div><div class="metric" id="eventsToday">—</div></div></div><div class="split"><section class="card events" id="events"><h2>Core Events</h2><div class="row"><span>Conversation Started</span><span class="badge">Automatic</span></div><div class="row"><span>Interested</span><span class="badge">Tag</span></div><div class="row"><span>Qualified</span><span class="badge">Tag</span></div><div class="row"><span>Purchased</span><span class="badge">Tag</span></div></section><section class="card"><h2>Receiver</h2><div class="platform"><span>YCloud webhook</span><span class="badge ready" id="receiver">Checking…</span></div><p class="muted">Webhook URL</p><div class="endpoint" id="endpoint"></div><p class="tiny" id="healthText"></p></section></div><section class="card" id="conversations"><h2>Incoming Conversations</h2><div class="tiny" style="margin:0 0 12px">Read-only marketing view. Replies stay in WhatsApp Business App.</div><div class="conversations" id="conversationList"><div class="empty">Waiting for data…</div></div></section><section class="card" id="platforms" style="margin-top:14px"><h2>Platform Connections</h2><div class="platform"><span>WhatsApp / YCloud</span><span class="badge">Receiver ready</span></div><div class="platform"><span>Meta native conversions</span><span class="badge pending">Next</span></div><div class="platform"><span>TikTok Messaging Events</span><span class="badge pending">Next</span></div><div class="platform"><span>Google Ads</span><span class="badge pending">Pending</span></div><div class="platform"><span>Snapchat / X / LinkedIn</span><span class="badge pending">Pending</span></div></section></main></div><script>
const $=id=>document.getElementById(id);$('endpoint').textContent=location.origin+'/webhook.php';function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
async function j(u,o){const r=await fetch(u,o);return r.json()}async function load(){const [h,s,c]=await Promise.all([j('api.php?action=health'),j('api.php?action=summary'),j('api.php?action=conversations')]);$('receiver').textContent=h.ok?'Ready':'Error';$('version').textContent=h.ok?'v'+h.version:'Error';$('healthText').textContent=h.ok?'Public receiver • persistent local storage • all YCloud events logged':'Backend error';if(s.ok){$('clientsCount').textContent=s.clients;$('numbersCount').textContent=s.whatsapp_numbers;$('conversationsCount').textContent=s.conversations;$('eventsToday').textContent=s.events_today}if(c.ok){const a=c.conversations;if(!a.length){$('conversationList').innerHTML='<div class="empty">No conversations received yet.</div>';return}$('conversationList').innerHTML=a.map(v=>`<div class="conv"><div class="conv-top"><div><div class="who">${esc(v.contact_name||v.customer_number)}</div><div class="client">${esc(v.business_number||'WhatsApp')} • ${esc(v.waba_id||'')}</div></div><div><span class="dir">${esc(v.last_direction||'')}</span><div class="meta">${v.last_message_at?new Date(v.last_message_at).toLocaleString():''}</div></div></div><div class="msg">${esc(v.last_message_text||'')}</div>${v.ctwa_clid?'<div class="ad">✓ Click-to-WhatsApp attribution captured</div>':''}<div class="tags">${['interested','qualified','purchased','lost'].map(t=>`<button class="tagbtn ${v.current_tag===t?'active':''}" onclick="tag('${v.id}','${t}')">${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div></div>`).join('')}}
async function tag(id,tagName){await j('api.php?action=tag',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({conversation_id:id,tag:tagName})});load()}load();setInterval(load,15000);
</script></body></html>
